import{_ as o,o as e,c as i,a2 as n}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"Glossario e linee guida per la traduzione (it/en)","description":"","frontmatter":{},"headers":[],"relativePath":"qa/i18n-glossary.md","filePath":"qa/i18n-glossary.md"}'),a={name:"qa/i18n-glossary.md"};function r(d,t,s,l,c,u){return e(),i("div",null,[...t[0]||(t[0]=[n('<h1 id="glossario-e-linee-guida-per-la-traduzione-it-en" tabindex="-1">Glossario e linee guida per la traduzione (it/en) <a class="header-anchor" href="#glossario-e-linee-guida-per-la-traduzione-it-en" aria-label="Permalink to &quot;Glossario e linee guida per la traduzione (it/en)&quot;">​</a></h1><p>Le stringhe dell&#39;interfaccia stanno solo nelle coppie <code>web/src/i18n/{en,it}.json</code> e <code>apps/desktop/frontend/src/i18n/{en,it}.json</code>. Questo documento fissa la terminologia italiana usata e le regole controllate automaticamente.</p><h2 id="controlli-automatici" tabindex="-1">Controlli automatici <a class="header-anchor" href="#controlli-automatici" aria-label="Permalink to &quot;Controlli automatici&quot;">​</a></h2><p>Test Vitest <code>src/i18n/consistency.test.ts</code> in <strong>entrambe</strong> le app (logica condivisa in <code>packages/ui/src/i18nCheck.ts</code>):</p><ul><li>stesso insieme di chiavi in <code>en</code> e <code>it</code>, nessun valore vuoto;</li><li>stessi segnaposto <code>{{x}}</code> (anche con formato, <code>{{x, number}}</code>) nelle due lingue;</li><li>stesse forme plurali: <code>_one</code>/<code>_other</code> in inglese; in italiano obbligatori <code>_one</code> e <code>_other</code>, <code>_many</code> facoltativo (CLDR: usato per i milioni);</li><li>nessuna chiave inutilizzata e nessuna chiave usata ma assente: scansione statica di <code>t(&#39;…&#39;)</code>, dei letterali che hanno la forma di una chiave e dei template literal con prefisso statico (<code>commands.${id}</code>, <code>editor.mode_${m}</code>, …); gli helper con ambito (<code>const t = (k) =&gt; i18next.t(\\</code>query.${k}`)`) sono riconosciuti;</li><li><code>&lt;html lang&gt;</code> segue la lingua (<code>web/src/i18n/i18n.test.tsx</code>, <code>apps/desktop/frontend/src/i18n/lang.test.ts</code>).</li></ul><p>Se una chiave è composta davvero a runtime in modo non rilevabile, si aggiunge alla lista <code>DYNAMIC</code> del test con un commento.</p><p><strong>Stringhe comuni (ADR-0043).</strong> Le stringhe uguali in console e workbench (<code>common.ok</code>, <code>common.cancel</code>, <code>common.close</code>, <code>common.retry</code>, <code>common.error</code>) e i messaggi degli errori dell&#39;API (<code>errors.&lt;CODICE&gt;</code>) stanno una sola volta in <code>packages/ui/src/i18n/{en,it}.json</code>, caricate da ogni app come namespace i18next <code>common</code> con <code>fallbackNS</code> (<code>withCommon</code> di <code>@clarae/ui/i18n</code>). Si chiamano sempre con <code>t(&#39;common.cancel&#39;)</code> o <code>t(&#39;errors.NOT_FOUND&#39;)</code>; una chiave dell&#39;app vince su quella comune, ma il test di consistenza fallisce se un&#39;app ridefinisce una chiave comune. <code>@clarae/cloud-features</code> non usa i18next e tiene il proprio dizionario.</p><p>Regole di scrittura: nessuna stringa visibile nel codice (nemmeno nei messaggi di <code>dialog.*</code>: usare <code>i18next.t</code>); numeri, date e dimensioni con <code>Intl</code> (<code>toLocaleString(lingua)</code>, <code>Intl.NumberFormat</code>) e mai formattati a mano; plurali con le chiavi <code>_one/_other</code> e <code>count</code>, mai concatenando una &quot;s&quot;.</p><h2 id="terminologia-italiana" tabindex="-1">Terminologia italiana <a class="header-anchor" href="#terminologia-italiana" aria-label="Permalink to &quot;Terminologia italiana&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concetto (en)</th><th>Termine italiano usato</th><th>Non usare / note</th></tr></thead><tbody><tr><td>vault</td><td><strong>vault</strong> (m.)</td><td>Non &quot;cassaforte&quot;, &quot;archivio&quot;, &quot;deposito&quot;. Invariato al plurale (&quot;i vault&quot;).</td></tr><tr><td>note</td><td><strong>nota</strong> / note</td><td>Non &quot;appunto&quot; (solo in &quot;Copia negli appunti&quot;, la clipboard di sistema).</td></tr><tr><td>folder</td><td><strong>cartella</strong></td><td>Non &quot;directory&quot;.</td></tr><tr><td>file</td><td><strong>file</strong> (invariabile)</td><td></td></tr><tr><td>sharing / share</td><td><strong>condivisione</strong> / condividere; il destinatario riceve un <strong>invito</strong></td><td>&quot;Share&quot; come sostantivo = &quot;condivisione&quot;.</td></tr><tr><td>mount (vault condiviso)</td><td><strong>condivisione ricevuta</strong> nel testo; &quot;mount&quot; solo nei contesti tecnici (admin)</td><td></td></tr><tr><td>group</td><td><strong>gruppo</strong></td><td>Non &quot;team&quot;.</td></tr><tr><td>sync / synchronization</td><td><strong>sincronizzazione</strong>; verbo &quot;sincronizzare&quot;; nella barra di stato &quot;Sync&quot; è ammesso come etichetta breve</td><td></td></tr><tr><td>conflict / conflict copy</td><td><strong>conflitto</strong> / <strong>copia di conflitto</strong></td><td></td></tr><tr><td>device</td><td><strong>dispositivo</strong></td><td></td></tr><tr><td>passphrase</td><td><strong>passphrase</strong></td><td>Non &quot;frase d&#39;accesso&quot;. Distinta dalla &quot;password&quot; dell&#39;account.</td></tr><tr><td>recovery key</td><td><strong>chiave di recupero</strong></td><td></td></tr><tr><td>private vault / shared vault</td><td><strong>vault privato</strong> / <strong>vault condiviso</strong></td><td>&quot;cifrato end-to-end&quot; per spiegare il privato.</td></tr><tr><td>trash</td><td><strong>cestino</strong></td><td>&quot;Sposta nel cestino&quot; (azione reversibile). &quot;Elimina&quot; = cancellazione definitiva o dell&#39;oggetto di amministrazione (utente, gruppo, profilo). Evitare &quot;cancella&quot;.</td></tr><tr><td>delete / remove</td><td><strong>elimina</strong> (distrugge) / <strong>rimuovi</strong> (toglie da un elenco, senza distruggere)</td><td></td></tr><tr><td>tab / pane</td><td><strong>scheda</strong> / <strong>pannello</strong></td><td>Il pannello è l&#39;area che contiene le schede.</td></tr><tr><td>sidebar</td><td><strong>barra laterale</strong></td><td>Nei nomi di chiavi resta <code>sidebar</code>.</td></tr><tr><td>settings</td><td><strong>impostazioni</strong></td><td>Non &quot;preferenze&quot;.</td></tr><tr><td>command palette</td><td><strong>palette comandi</strong></td><td></td></tr><tr><td>quick switcher</td><td><strong>selettore rapido</strong></td><td></td></tr><tr><td>backlink</td><td><strong>backlink</strong></td><td>Invariato (anglicismo consolidato nel dominio).</td></tr><tr><td>tag</td><td><strong>tag</strong></td><td>&quot;etichetta&quot; solo per il testo di un&#39;etichetta grafica (arco del grafo, canvas).</td></tr><tr><td>properties</td><td><strong>proprietà</strong></td><td>Non &quot;attributi&quot;.</td></tr><tr><td>graph view</td><td><strong>vista grafo</strong></td><td>Non &quot;grafico&quot;.</td></tr><tr><td>canvas</td><td><strong>lavagna</strong></td><td></td></tr><tr><td>drawing</td><td><strong>disegno</strong></td><td></td></tr><tr><td>template</td><td><strong>template</strong></td><td></td></tr><tr><td>daily note</td><td><strong>nota giornaliera</strong></td><td></td></tr><tr><td>bookmark</td><td><strong>segnalibro</strong></td><td></td></tr><tr><td>config profile</td><td><strong>profilo di configurazione</strong></td><td>Breve: &quot;profilo&quot;.</td></tr><tr><td>quota</td><td><strong>quota</strong></td><td></td></tr><tr><td>audit log</td><td><strong>registro di audit</strong></td><td></td></tr><tr><td>history / revision</td><td><strong>cronologia</strong> / <strong>versione</strong> (revisione solo nel contesto del server)</td><td></td></tr><tr><td>read-only</td><td><strong>sola lettura</strong></td><td>Livelli: <strong>Lettore</strong>, <strong>Editor</strong>, <strong>Gestore</strong>.</td></tr><tr><td>administrator / admin</td><td><strong>amministratore</strong></td><td></td></tr><tr><td>suspend / reactivate</td><td><strong>sospendi</strong> / <strong>riattiva</strong></td><td>Stato &quot;Sospeso&quot;.</td></tr></tbody></table><h2 id="tono-e-punteggiatura" tabindex="-1">Tono e punteggiatura <a class="header-anchor" href="#tono-e-punteggiatura" aria-label="Permalink to &quot;Tono e punteggiatura&quot;">​</a></h2><ul><li>Rivolgersi all&#39;utente con il <strong>tu</strong> nell&#39;interfaccia dell&#39;app (&quot;Collegalo al cloud…&quot;, &quot;Scegli una passphrase&quot;), e in modo impersonale nei messaggi di sistema; la documentazione usa il <strong>voi</strong>. Non mescolare &quot;tu&quot; e &quot;Lei&quot;.</li><li>Virgolette: <strong>«caporali»</strong> per i nomi (file, vault, utenti) nei messaggi; niente virgolette inglesi o dritte nelle stringhe italiane.</li><li>Puntini di sospensione <code>…</code> (un solo carattere) per le azioni che aprono una finestra (&quot;Importa…&quot;).</li><li>Maiuscola solo all&#39;inizio della frase e per i nomi propri; i titoli dei pulsanti non vanno in Title Case.</li><li>I messaggi di errore dicono cosa è successo e cosa fare, senza codici interni; i codici (<code>QUOTA_EXCEEDED</code>, …) restano nei log e nel campo <code>code</code> dell&#39;API.</li></ul><h2 id="riesame-del-ciclo-m7" tabindex="-1">Riesame del ciclo M7 <a class="header-anchor" href="#riesame-del-ciclo-m7" aria-label="Permalink to &quot;Riesame del ciclo M7&quot;">​</a></h2><p>Correzioni applicate: uniformate le virgolette a «caporali» (16 stringhe), &quot;cancellati&quot; → &quot;eliminati&quot; in un messaggio di amministrazione, rimosso &quot;(in arrivo)&quot; da una descrizione ormai obsoleta (la condivisione esiste), <code>Error</code> fisso in <code>dialog.error</code> spostato in i18n, etichetta dell&#39;editor tradotta, formati di data/numero resi locali (<code>toLocaleString(lingua)</code> / <code>Intl.NumberFormat</code>), rimosse 12 chiavi inutilizzate. Aperte: nessuna terminologia in conflitto residua rilevata; resta una revisione da parte di un madrelingua prima del rilascio.</p>',14)])])}const p=o(a,[["render",r]]);export{m as __pageData,p as default};
